import assert from "node:assert/strict";
import * as fs from "node:fs";

const read = (file) => fs.readFileSync(file, "utf8");
const pkg = JSON.parse(read("package.json"));
const tools = JSON.parse(read(".github/release-tools/package.json"));
const toolsLock = JSON.parse(read(".github/release-tools/package-lock.json"));
const renovate = JSON.parse(read(".github/renovate.json"));
assert.deepEqual(Object.keys(tools.dependencies).sort(), ["conventional-commits-parser", "semver"]);
assert.deepEqual(toolsLock.packages[""].dependencies, tools.dependencies, "locked coordinator dependencies differ from package manifest");
assert.equal(tools.engines.node, ">=22.19.0");
assert.equal(pkg.name, "@soulwaxx/pi-skill-autocomplete");
assert.match(pkg.version, /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$/);
assert.ok(pkg.files.includes("README.md") && pkg.files.includes("LICENSE"));
for (const [name, command] of Object.entries({ "release:check": "node .github/release-tools/check.mjs", "test:release": "node tests/run-release-tests.mjs" })) assert.equal(pkg.scripts[name], command, `${name} script path changed unexpectedly`);
for (const file of fs.readdirSync(".github/workflows").filter((name) => name.endsWith(".yml"))) {
  const text = read(`.github/workflows/${file}`);
  for (const match of text.matchAll(/^\s+uses:\s+([^\s]+)/gm)) assert.match(match[1], /@[0-9a-f]{40}$/);
  assert.match(text, /^permissions:\n\s+contents: read\s*$/m, `${file} must default to read-only permissions`);
}
const ci = read(".github/workflows/test.yml");
const release = read(".github/workflows/release.yml");
const verifyJob = release.split("\n  publish:")[0];
const publishJob = (release.split("\n  publish:")[1] ?? "").split("\n  bootstrap:")[0];
const bootstrapJob = release.split("\n  bootstrap:")[1] ?? "";
const prTitle = read(".github/workflows/pr-title.yml");
assert.match(ci, /os: \[ubuntu-latest, macos-latest\]/);
assert.match(ci, /node: \['22', '24'\]/);
assert.match(ci.split("\n  workflow-validation:")[0], /fetch-depth: 0/, "release regression tests need the immutable initial source history");
assert.match(ci, /types: \[opened, synchronize, reopened, edited\]/);
assert.match(ci, /name: CI passed/);
assert.match(ci, /needs: \[test, workflow-validation\]/);
assert.match(ci, /retention-days: 30/);
assert.match(ci, /actionlint_1\.7\.11_linux_amd64\.tar\.gz/);
assert.match(ci, /900919a84f2229bac68ca9cd4103ea297abc35e9689ebb842c6e34a3d1b01b0a/);
assert.match(release, /workflow_dispatch:/);
assert.match(release, /recovery_tag:/);
assert.match(release, /cancel-in-progress: false/);
assert.match(release, /contents: write\s+id-token: write/);
assert.match(release, /actions\/download-artifact@9000827ccba6bdab643e8b6fd33ac0654aef8333 # v8\.0\.2/);
assert.match(release, /npm install --global npm@11\.21\.0 --ignore-scripts/);
assert.match(release, /PREPARED_INTEGRITY/);
assert.match(verifyJob, /GH_TOKEN: \$\{\{ github\.token \}\}/);
assert.match(verifyJob, /release-source\.mjs verify "\$TRUSTED_SHA"/);
assert.match(verifyJob, /node \.github\/release-tools\/release-source\.mjs verify "\$SHA"/);
assert.match(verifyJob, /npm run check && npm run test:feasibility && npm run test:artifact && npm run bench/);
assert.match(verifyJob, /npm audit --audit-level=critical/);
assert.match(verifyJob, /release\.mjs prepare/);
assert.match(verifyJob, /actions\/upload-artifact@/);
assert.match(publishJob, /contents: write\s+id-token: write/);
assert.match(publishJob, /actions\/download-artifact@/);
assert.match(publishJob, /Confirm verified main is still current before publication/);
assert.match(publishJob, /publish-prepared\.mjs/);
assert.match(publishJob, /!inputs\.bootstrap_npm/);
assert.doesNotMatch(publishJob, /BOOTSTRAP_NPM_TOKEN|secrets\./);
assert.doesNotMatch(verifyJob, /secrets\./);
assert.match(bootstrapJob, /github\.event_name == 'workflow_dispatch'/);
assert.match(bootstrapJob, /inputs\.bootstrap_npm/);
assert.match(bootstrapJob, /inputs\.recovery_tag == 'v0\.1\.0'/);
assert.match(bootstrapJob, /inputs\.bootstrap_confirmation == 'publish-v0\.1\.0'/);
assert.match(bootstrapJob, /contents: read\s+id-token: write/);
assert.doesNotMatch(bootstrapJob, /contents: write/);
assert.match(bootstrapJob, /BOOTSTRAP_NPM_TOKEN: \$\{\{ secrets\.NPM_BOOTSTRAP_TOKEN \}\}/);
assert.match(bootstrapJob, /bootstrap-prepared\.mjs/);
assert.doesNotMatch(publishJob, /npm run (check|test)|npm ci --ignore-scripts/);
assert.doesNotMatch(release, /semantic-release|release\.config\.mjs|Refuse unimplemented bootstrap|release\.mjs run/);
assert.match(prTitle, /edited/);
assert.match(prTitle, /Conventional Commit title/);
const dependabot = read(".github/dependabot.yml");
assert.match(dependabot, /package-ecosystem: npm[\s\S]*directory: "\/"/);
assert.match(dependabot, /directory: "\/.github\/release-tools"/);
assert.match(dependabot, /package-ecosystem: github-actions/);
assert.equal(renovate.customManagers.length, 2);
assert.ok(renovate.customManagers.some((manager) => manager.depNameTemplate === "npm"));
assert.ok(renovate.customManagers.some((manager) => manager.depNameTemplate === "rhysd/actionlint"));
console.log(`Release configuration, scripts, split workflow permissions, and update maintenance checked for ${pkg.name}@${pkg.version}`);
